"""Methods generated by the inventory (Implementation Decision 17; ticket 108).

The seam is a temporary project's `research/sections/methods.md` as a render writes it, `research/OUTLINE.md`, and
`research/methods_inventory.json`, with the start-midway fixture's code (ticket 78) committed on `main`. The current
results' `parameters` are what the conductor keeps beside each integrated attempt's session (`methods.json`, ticket
107); the locks are the ones ticket 106 renders under `code/locks/`. At setup at a start midway the parsers run through
the tool runner's recordings and the reading through the fake launcher.
"""

import json
import sys

from tests.test_documents import MIDWAY
from tests.test_drawings import DrawingRunCase
from tests.test_methods import PY_SECOND, MATLAB, MethodsCase, Recorded
from tests.test_verification import SetupCase, VerificationCase
from wayline import drawings, methods, methods_inventory, sections, verification, worker
from wayline.conductor import SECTIONS_CHECK
from wayline.tools import Tools
from wayline.ledger import Ledger

WINDOW_REASON = "A 512-sample window spans two wingbeats at 2000 frames per second."


class InventoryCase(MethodsCase):
    def setUp(self):
        super().setUp()
        self.on_main({"phaselock.py": PY_SECOND, "phaselock.m": MATLAB})

    def integrated(self, ticket, parameters, attempt=1):
        """What `_close` keeps beside an integrated attempt's session: its filled `parameters` (ticket 107)."""
        methods.write_code_rule(worker.session_dir(self.project, ticket, attempt), {"parameters": parameters, "not_methods": []})

    def window(self, reason=WINDOW_REASON, line=13):
        return {"method": "order_parameter", "name": "window", "value": "512", "default": "256", "path": "code/phaselock.py",
                "line": line, "reason": reason}

    def render(self):
        sections.render_section(self.ledger, "methods")
        return (self.project / "research" / "sections" / "methods.md").read_text(encoding="utf-8")

    def rows(self, text):
        return [line for line in text.splitlines() if line.startswith("| ") and "order_parameter" in line]


class ParameterTableTest(InventoryCase):
    def test_every_render_of_methods_carries_the_table_from_the_current_results_parameters(self):
        self.integrated(3, [self.window()])
        text = self.render()
        self.assertIn("## Parameters", text)
        self.assertIn("| Method | Parameter | Value | Default | Reason | Code |", text)
        self.assertEqual(self.rows(text), ["| `order_parameter` | `window` | 512 | 256 | %s | {code:code/phaselock.py#L13} |"
                                           % WINDOW_REASON])

    def test_a_later_tickets_entry_replaces_the_earlier_and_a_file_main_no_longer_holds_leaves(self):
        self.integrated(3, [self.window("An early reason.")])
        self.integrated(5, [self.window(), {"method": "phaselock", "name": "window", "value": "512", "default": None,
                                            "path": "code/gone.m", "line": 3, "reason": "Gone with its file."}])
        text = self.render()
        self.assertEqual(len(self.rows(text)), 1)
        self.assertIn(WINDOW_REASON, text)
        self.assertNotIn("An early reason.", text)
        self.assertNotIn("Gone with its file.", text)

    def test_the_table_is_never_read_as_the_owners_passages(self):
        self.integrated(3, [self.window()])
        self.render()
        self.render()
        self.assertEqual([item for item in sections.read_passages(self.ledger) if item.get("section") == "methods"], [])


class OwnerReasonTest(InventoryCase):
    OWNERS = "Two wingbeats is the shortest span over which the phase is defined."

    def test_a_reason_edited_in_the_table_is_taken_in_as_the_owners_passage_and_later_renders_show_it(self):
        self.integrated(3, [self.window()])
        path = self.project / "research" / "sections" / "methods.md"
        text = self.render()
        path.write_text(text.replace(WINDOW_REASON, self.OWNERS), encoding="utf-8")
        text = self.render()
        self.assertEqual(self.rows(text), ["| `order_parameter` | `window` | 512 | 256 | %s | {code:code/phaselock.py#L13} |"
                                           % self.OWNERS])
        reasons = [item for item in sections.read_passages(self.ledger) if item.get("parameter")]
        self.assertEqual([(item["by"], item["section"], item["parameter"], item["text"]) for item in reasons],
                         [("owner", "methods", "order_parameter:window@code/phaselock.py", self.OWNERS)])
        events = [event["payload"] for event in Ledger(self.project).read_events()[0] if event["event"] == "passage"]
        self.assertEqual(events[-1]["parameter"], "order_parameter:window@code/phaselock.py")
        self.assertNotIn(self.OWNERS, text.split(sections.INVENTORY)[0], "a reason is the table's, never the section's text")
        # A later ticket's reason for the same row does not displace the owner's.
        self.integrated(4, [self.window("A newer reason from a ticket.")])
        self.assertIn(self.OWNERS, self.render())

    def test_a_reason_said_in_conversation_is_the_same_passage(self):
        import contextlib
        import io
        from wayline import cli
        self.integrated(3, [self.window()])
        self.render()
        with contextlib.redirect_stdout(io.StringIO()):
            code = cli.main(["passage", "add", "--section", "methods", "--heading", "Parameters", "--parameter",
                             "order_parameter:window", self.OWNERS, "--project", str(self.project)])
        self.assertEqual(code, 0)
        self.assertIn("| %s |" % self.OWNERS, self.render())

    def test_an_edit_of_the_passages_above_the_table_leaves_the_table_alone(self):
        self.integrated(3, [self.window()])
        self.methods_passage("The phase is taken from the analytic signal {code:code/phaselock.py#order_parameter}.")
        path = self.project / "research" / "sections" / "methods.md"
        text = self.render()
        path.write_text(text.replace("The phase is taken", "Each phase is taken"), encoding="utf-8")
        self.render()
        self.assertEqual([item for item in sections.read_passages(self.ledger) if item.get("parameter")], [])


REQUIREMENTS = "# uv pip freeze of <project>/.venv (wayline tools package python)\nnumpy==1.26.4\nscipy==1.11.4\n"
OCTAVE_LIST = ("% pkg list of the Octave Forge packages this project uses (wayline tools package octave)\n"
               "Package Name  | Version | Installation directory\n--------------+---------+-----------------------\n"
               "      signal *|   1.4.5 | /prefix/share/octave/packages/signal-1.4.5\n")


class SoftwareTest(InventoryCase):
    def lock(self, name, text, commit="a" * 40):
        path = self.project / "code" / "locks" / commit / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")

    def test_methods_lists_the_software_and_exact_versions_from_the_locks_in_code(self):
        self.lock("requirements.lock", REQUIREMENTS)
        self.lock("requirements.lock", REQUIREMENTS.replace("1.26.4", "2.0.1"), commit="b" * 40)
        self.lock("octave-packages.lock", OCTAVE_LIST)
        tools = self.project / "code" / "locks" / "tools.json"
        tools.write_text(json.dumps({"tools": [{"name": "octave", "version": "9.2.0", "lock": "c0ffee", "runs": ["r1"]}]}))
        text = self.render()
        software = text.split("## Software", 1)[1]
        self.assertIn("- Python: numpy 1.26.4 and 2.0.1, scipy 1.11.4", software)
        self.assertIn("- Octave Forge: signal 1.4.5", software)
        self.assertIn("- Tools: octave 9.2.0", software)

    def test_before_any_lock_is_rendered_the_projects_own_locks_are_read(self):
        (self.project / "code" / "requirements.lock").write_text(REQUIREMENTS, encoding="utf-8")
        self.assertIn("- Python: numpy 1.26.4, scipy 1.11.4", self.render())

    def test_no_lock_and_no_parameter_adds_nothing_to_methods(self):
        self.assertNotIn(sections.INVENTORY, self.render())


PYSINDY_CFF = """cff-version: 1.2.0
message: "If you use this software, please cite it as below."
title: "pysindy"
preferred-citation:
  type: article
  title: "PySINDy: A Python package for the sparse identification of nonlinear dynamical systems from data"
  authors:
    - family-names: "de Silva"
      given-names: "Brian M."
  year: 2020
  doi: "10.21105/joss.02104"
"""


class CitationTest(SoftwareTest):
    def installed(self, module, files):
        root = self.project / ".venv" / "lib" / "python3.12" / "site-packages" / module
        root.mkdir(parents=True, exist_ok=True)
        for name, text in files.items():
            (root / name).write_text(text, encoding="utf-8")

    def citations(self, text):
        return text.split("## Proposed citations", 1)[1] if "## Proposed citations" in text else ""

    def test_a_citation_is_proposed_only_for_a_relied_on_package_that_publishes_a_preferred_citation(self):
        self.lock("requirements.lock", REQUIREMENTS + "pysindy==1.7.5\numap-learn==0.5.5\n")
        self.installed("pysindy", {"CITATION.cff": PYSINDY_CFF})
        analytic = self.methods_passage("The phase is taken from the analytic signal {code:code/phaselock.py#order_parameter}.")
        sindy = self.methods_passage("The dynamics were identified with SINDy.", heading="Dynamics")
        self.methods_passage("Moths were embedded with UMAP.", heading="Embedding")
        listed = self.citations(self.render())
        # scipy: relied on (the analytic signal is its Hilbert transform), publishes its preferred citation (CITATION.bib).
        self.assertIn("- scipy (Hilbert transform, %s)" % analytic["id"], listed)
        self.assertIn("10.1038/s41592-019-0686-2", listed)
        # pysindy: relied on, and the package as installed carries a CITATION.cff.
        self.assertIn("- pysindy (SINDy, %s)" % sindy["id"], listed)
        self.assertIn("10.21105/joss.02104", listed)
        self.assertIn("PySINDy: A Python package for the sparse identification", listed)
        # numpy: no Methods passage relies on its method; umap-learn: relied on, and publishes no preferred citation.
        self.assertNotIn("numpy", listed)
        self.assertNotIn("umap", listed)

    def test_a_package_the_locks_do_not_hold_gets_no_citation(self):
        self.methods_passage("The phase is taken from the analytic signal {code:code/phaselock.py#order_parameter}.")
        self.assertEqual(self.citations(self.render()), "")


class MethodsToCodeTest(InventoryCase):
    """The rule from Methods to code is no gate: a method with no code behind it is a gap, and is not reproduced."""

    def outline(self):
        from wayline import outline
        outline.render_outline(self.ledger)
        return (self.project / "research" / "OUTLINE.md").read_text(encoding="utf-8")

    def gaps(self, text):
        return text.split("## Gaps", 1)[1].split("\n## ", 1)[0]

    def test_a_methods_passage_naming_a_method_with_no_code_behind_it_is_a_gap_never_failed(self):
        backed = self.methods_passage("The phase is taken from the analytic signal.")
        filtered = self.methods_passage("Each trace was band-passed with a Butterworth filter.", heading="Filtering")
        missing = self.methods_passage("The drift is fitted by least squares {code:code/drift.py#fit_drift}.", heading="Drift")
        gaps = self.gaps(self.outline())
        self.assertIn('Methods: "Filtering" names Butterworth (%s), which no code under `code/` calls' % filtered["id"], gaps)
        self.assertIn('Methods: "Drift" names {code:code/drift.py#fit_drift} (%s)' % missing["id"], gaps)
        self.assertNotIn(backed["id"], gaps)
        record = methods_inventory.read_record(self.ledger)
        self.assertEqual(sorted(entry["passage"] for entry in record["not_reproduced"]), sorted([filtered["id"], missing["id"]]))
        self.assertTrue(all(entry["reproduced_by_repository"] is False for entry in record["not_reproduced"]))
        # Never failed: the section renders, and the Methods passages all stand.
        self.assertEqual(sections.current_ids(self.ledger, "methods"), {backed["id"], filtered["id"], missing["id"]})

    def test_code_written_later_takes_the_method_out_of_the_gaps(self):
        filtered = self.methods_passage("Each trace was band-passed with a Butterworth filter.", heading="Filtering")
        self.assertIn(filtered["id"], self.gaps(self.outline()))
        self.on_main({"filters.py": "from scipy.signal import butter\n\n\ndef band(order=4):\n    return butter(order, [20, 60])\n"})
        self.assertNotIn(filtered["id"], self.gaps(self.outline()))

    def test_the_outlines_methods_part_gains_the_parameter_table_line(self):
        methods.write_code_rule(worker.session_dir(self.project, 3, 1), {"parameters": [
            {"method": "order_parameter", "name": "window", "value": "512", "default": "256", "path": "code/phaselock.py",
             "line": 13, "reason": WINDOW_REASON}], "not_methods": []})
        part = self.outline().split("\n## Methods", 1)[1].split("\n## ", 1)[0]
        self.assertIn("- Parameter table: 1 parameter, generated at the end of Methods", part)


class DrawingMethodsTest(DrawingRunCase):
    """A drawing whose numbers.json computes a number a finding cites returns the Methods passage that says how."""

    FINDING = {"text": "Across the 3 seeds the AUROC never falls below 0.71.", "heading": "What the plots show",
               "provenance": "drawings/R1-1/numbers.json#auroc", "negative": False, "replaces": None}
    PASSAGE = {"section": "methods", "heading": "Drawing R1", "replaces": None,
               "text": "The lowest AUROC across seeds is the minimum of the per-seed AUROC the drawing's script reads."}

    def respond(self, passages):
        drawn = self.plotter()

        def respond(request, message):
            envelope = drawn(request, message)
            envelope.structured_output["findings"] = [dict(self.FINDING)]
            envelope.structured_output["passages"] = [dict(item) for item in passages]
            return envelope
        return respond

    def test_a_cited_drawing_number_without_its_methods_passage_is_sent_back_and_one_with_it_is_filed(self):
        self.run_drawings(self.respond([]), self.respond([self.PASSAGE]))
        checks = [result for event in self.events("acceptance") if event["payload"]["where"] == "worktree"
                  for result in event["payload"]["results"] if result["cmd"] == SECTIONS_CHECK]
        self.assertEqual(checks[0]["exit_code"], 1)
        self.assertIn("numbers.json", checks[0]["tail"])
        self.assertIn("Methods passage", checks[0]["tail"])
        self.assertEqual(checks[-1]["exit_code"], 0)
        filed = [item for item in sections.read_passages(self.project) if item["section"] == "methods"]
        self.assertEqual([(item["by"], item["heading"]) for item in filed], [("t2-a1", "Drawing R1")])

    def test_a_drawing_whose_findings_cite_no_number_of_its_owes_no_methods_passage(self):
        self.assertEqual(drawings.methods_owed({"kind": "drawing", "origin": "drawing R1-1 at run_end"},
                                               {"findings": [dict(self.FINDING, provenance="results/summary.json#auroc")]}), [])
        self.assertEqual(drawings.methods_owed({"kind": "drawing", "origin": "drawing R1-1 at run_end"},
                                               {"findings": [dict(self.FINDING)]}), ["drawings/R1-1/numbers.json#auroc"])


class SetupTest(VerificationCase):
    """At setup at a start midway (the fixture of ticket 78): the inherited Methods compared with the code, and the
    inherited code read once per file with developed code, its concerns attached as leads."""

    def setUp(self):
        super().setUp()
        self.add(MIDWAY / "methods.tex")
        self.deconstruct("D2")
        code = self.project / "code"
        code.mkdir(exist_ok=True)
        (code / "phaselock.py").write_text(PY_SECOND, encoding="utf-8")
        (code / "phaselock.m").write_text(MATLAB, encoding="utf-8")
        (code / "README.md").write_text("The lantern moths.\n", encoding="utf-8")
        self.parsers = Recorded()
        self.parser_tools = Tools(root=self.temp / "parser-tools", record={"tools": {"tree-sitter-matlab": {
            "executable": sys.executable, "version": "1.3.1", "env": {}, "route": "uv"}}})

    def leads(self, path):
        if path.endswith(".py"):
            return {"leads": [{"text": "colony_synchrony fixes the window at 512 while order_parameter's default is 256, so "
                                       "the two entry points disagree on what a figure used.", "item": "window=512", "line": 13},
                              {"text": "The traces are never band-passed here.", "item": "bandpass(", "line": 7}]}
        return {"leads": [{"text": "The MATLAB port defaults the window to 512 where the Python defaults to 256.",
                           "item": "window = 512", "line": 3}]}

    def setup(self):
        def respond(request, message):
            path = "code/phaselock.py" if "code/phaselock.py" in request.prompt else "code/phaselock.m"
            return worker.Envelope(structured_output=self.leads(path), session_id="lead-%s" % path[-2:], num_turns=1,
                                   usage={"input_tokens": 700, "output_tokens": 90})

        with worker.use_fake() as fake:
            fake.script(respond=respond, role=methods.READER)
            fake.script(respond=respond, role=methods.READER)
            done = methods_inventory.setup(self.project, run=self.parsers, tools=self.parser_tools)
            self.calls = list(fake.calls)
        return done

    def test_each_disagreement_between_the_stated_and_the_codes_parameters_is_filed_into_the_verification(self):
        self.setup()
        [result] = verification.read_results(self.project)
        texts = [entry["text"] for entry in result["disagreements"]]
        stated = next(item["id"] for item in self.ours("D2"))
        self.assertTrue(any("`window`" in text and "256" in text and "512" in text and "code/phaselock.py:13" in text
                            and stated in text for text in texts), texts)
        self.assertTrue(any("`window`" in text and "512" in text and "code/phaselock.m:3" in text for text in texts), texts)
        self.assertFalse(any("hilbert" in text.lower() for text in texts), "the analytic signal the Methods states is the code's")
        self.assertEqual(len([text for text in texts if "code/phaselock.py:6" in text]), 0,
                         "order_parameter's own default of 256 agrees with the stated window")
        pack = verification.pack_text(self.project, {"verifies": "Results"})
        self.assertIn("## Where the inherited Methods and the code disagree", pack)
        self.assertIn("code/phaselock.py:13", pack)

    def test_one_sonnet_reading_per_file_with_developed_code_its_items_grep_checked_its_concerns_attached_as_leads(self):
        done = self.setup()
        self.assertEqual(len(self.calls), 2, "phaselock.py and phaselock.m develop methods; README.md is no code")
        self.assertEqual({(call.request.model, call.request.effort) for call in self.calls}, {("sonnet", "medium")})
        [result] = verification.read_results(self.project)
        leads = [entry["text"] for entry in result["leads"]]
        self.assertEqual(len(leads), 2)
        self.assertTrue(any("two entry points disagree" in text for text in leads))
        self.assertFalse(any("band-passed" in text for text in leads), "grep finds no bandpass( in the file: dropped")
        record = methods_inventory.read_record(self.project)["setup"]
        self.assertEqual(sorted(entry["path"] for entry in record["readings"]), ["code/phaselock.m", "code/phaselock.py"])
        self.assertEqual(record["leads"], 2)
        self.assertTrue(any("bandpass(" in item for item in record["dropped"]))
        self.assertIn("Leads from the reading of the inherited code", verification.pack_text(self.project, {"verifies": "Results"}))
        self.assertIn("lead", (self.project / "research" / "VERIFICATIONS.md").read_text(encoding="utf-8"))
        self.assertEqual(done, record)

    def test_the_setup_runs_once(self):
        self.setup()
        with worker.use_fake() as fake:
            methods_inventory.setup(self.project, run=self.parsers, tools=self.parser_tools)
            self.assertEqual(fake.calls, [], "nothing is read again")

    def test_a_project_that_did_not_start_midway_gets_no_setup(self):
        from wayline.project import init_project
        other = self.temp / "fresh"
        init_project(other, harness_root=self.fake_harness(), git=False, hermes_python=None, owner_email=None)
        self.assertIsNone(methods_inventory.setup(other, run=self.parsers, tools=self.parser_tools))


class PositionSetupTest(SetupCase):
    """The setup's comparison and reading run in the position step, once the critic's memo records the verifications."""

    def test_the_position_step_compares_and_reads_the_inherited_code(self):
        from wayline import position
        from wayline.worker import Envelope

        self.add(MIDWAY / "methods.tex")
        self.deconstruct("D4")
        (self.project / "code").mkdir(exist_ok=True)
        (self.project / "code" / "phaselock.py").write_text(PY_SECOND, encoding="utf-8")
        lead = {"leads": [{"text": "The window is 512 here and 256 by default.", "item": "window=512", "line": 13}]}
        with worker.use_fake() as fake:
            fake.script(Envelope(structured_output=self.memo(), session_id="critic-1", num_turns=3), role=position.CRITIC)
            fake.script(Envelope(structured_output=lead, session_id="lead-1", num_turns=1), role=methods.READER)
            report = position.position(self.project, notify=lambda *args: None)
        self.assertTrue(any("compared the inherited Methods with the code" in line for line in report["did"]), report["did"])
        [result] = verification.read_results(self.project)
        self.assertEqual([entry["text"] for entry in result["leads"]], ["The window is 512 here and 256 by default."])
        self.assertTrue(any("`window`" in entry["text"] for entry in result["disagreements"]))
